// Curated celebration phrases for the Practice Receipt.
// Picked at random from this list — never generated by an AI model at runtime.
export const celebrations = {
  en: [
    "You nailed it!",
    "Nice one!",
    "Solid round!",
    "Well played!",
    "That was good!",
    "You had a point!",
    "Great round!",
    "You showed up!",
    "That one was yours.",
    "Round complete!",
  ],
  fr: [
    "T'as assuré !",
    "T'as géré !",
    "Bien joué !",
    "Pas mal du tout !",
    "Solide !",
    "Franchement, bien joué !",
    "Celle-là était bonne !",
    "Beau round !",
  ],
};

export function randomCelebration(lang) {
  const list = celebrations[lang] || celebrations.en;
  return list[Math.floor(Math.random() * list.length)];
}
